<body style="margin:0;padding:0;background:transparent;">
<div id="iseria-db-panel"></div>
<script>
(function(){
  'use strict';
  var host = document.getElementById('iseria-db-panel');

  function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

  function accentOf(title){
    if(title.indexOf('世界书') !== -1) return 'wb';
    if(title.indexOf('历史') !== -1) return 'hist';
    if(title.indexOf('核查') !== -1 || title.indexOf('行为') !== -1) return 'check';
    return 'misc';
  }

  function parseSections(text){
    var parts = String(text).split(/(?=【)/).filter(function(p){ return p.trim(); });
    if(!parts.length || (parts.length === 1 && text.indexOf('【') === -1))
      return [{ title: '索引结果', body: text.trim() }];
    return parts.map(function(p){
      var m = p.match(/^(【[^】]+】)\s*([\s\S]*)$/);
      if(m) return { title: m[1].replace(/[【】]/g,''), body: m[2].trim() };
      return { title: '', body: p.trim() };
    });
  }

  function pillHTML(cls, orn, label){
    return '<div class="dbp-pill ' + cls + '">'
      + '<span class="dbp-pill__orn">✦</span>'
      + '<span>类数据库 · ' + esc(label) + '</span>'
      + (cls.indexOf('dim') === -1 ? '<span class="dbp-pill__arrow" id="dbp-arrow">▾</span>' : '')
      + '</div>';
  }

  function expandedHTML(text, floor){
    var secs = parseSections(text);
    var cards = secs.map(function(s){
      var acc = accentOf(s.title);
      var empty = !s.body || s.body === '无';
      return '<div class="dbp-card dbp-card--' + acc + (empty ? ' dbp-card--empty' : '') + '">'
        + '<div class="dbp-card__title"><span class="dbp-card__dot"></span>' + esc(s.title || '备注') + '</div>'
        + '<div class="dbp-card__body">' + esc(s.body || '（本段无内容）') + '</div>'
        + '</div>';
    }).join('');
    return '<div class="dbp-wrap">'
      + '<div class="dbp-frame">'
      + '<div class="dbp-head"><span class="dbp-head__orn">✦</span>'
      + '<span class="dbp-head__title">类 数 据 库</span>'
      + '<span class="dbp-head__floor">第' + esc(floor) + '楼 · 三段上下文</span></div>'
      + cards
      + '<div class="dbp-foot">— 仅注入提示词 · 不入聊天档案 · 点击收起 —</div>'
      + '</div></div>';
  }

  function bindPill(text, floor){
    var p = host.querySelector('.dbp-pill');
    if(!p) return;
    p.addEventListener('click', function(){
      host.innerHTML = expandedHTML(text, floor) + pillHTML('dbp-pill--live', '✦', '已索引');
      var last = host.lastElementChild;
      last.addEventListener('click', function(){ renderCollapsed(text, floor); });
      var w = host.querySelector('.dbp-wrap');
      if(w) w.addEventListener('click', function(e){ if(e.target === w) renderCollapsed(text, floor); });
    });
  }

  function renderCollapsed(text, floor){
    host.innerHTML = pillHTML('dbp-pill--live', '✦', '已索引');
    bindPill(text, floor);
  }

  function fetchLast(){
    try{
      var s = JSON.parse(localStorage.getItem('iseria_db_outputs') || 'null');
      if (s && s.text) return { floor: Number(s.floor), text: s.text };
    }catch(e){}
    try{
      var v = getVariables({ type: 'chat' }) || {};
      var outs = v['iseria_db_outputs'] || v['isuria_db_outputs'] || {};
      var keys = Object.keys(outs).map(Number).sort(function(a,b){ return b - a; });
      if(!keys.length) return null;
      return { floor: keys[0], text: outs[keys[0]] || '' };
    }catch(e){ return null; }
  }

  function dbEnabled(){
    try{
      var c = JSON.parse(localStorage.getItem('iseria_db_cfg') || 'null');
      if (c && typeof c.enabled === 'boolean') return c.enabled;
    }catch(e){}
    return true; /* 读不到配置时不因门控隐藏（面板本身只在开启时才有数据可显示） */
  }

  var myFloor = -1;
  try{ myFloor = getCurrentMessageId(); }catch(e){}

  var last = fetchLast();
  if(last && last.floor === myFloor && last.text && dbEnabled()){
    renderCollapsed(last.text, myFloor);
  } else if(myFloor >= 0){
    if(!dbEnabled()){ host.innerHTML = ''; host.classList.add('is-empty'); }
    else {
    host.innerHTML = pillHTML('dbp-pill--dim', '✦', '索引中…');
    var tries = 0;
    var done = false;
    var tryRender = function(){
      last = fetchLast();
      if(last && last.floor === myFloor && last.text && dbEnabled()){
        done = true;
        clearInterval(timer);
        renderCollapsed(last.text, myFloor);
      } else if(!dbEnabled()){
        done = true;
        clearInterval(timer);
        host.innerHTML = '';
        host.classList.add('is-empty');
      }
    };
    var timer = setInterval(function(){
      tries++;
      tryRender();
      if(done) return;
      if(tries > 150){
        clearInterval(timer);
        host.innerHTML = '';   /* 本楼不是最新索引目标：完全不显示 */
        host.classList.add('is-empty');
      }
    }, 400);
    /* localStorage 同源事件：分析写盘即刻点亮，不干等轮询 */
    try{
      window.addEventListener('storage', function(){ if(!done) tryRender(); });
    }catch(e){}
    }
  } else {
    host.classList.add('is-empty');
  }
})();
</script>
</body>
</html>
